-- Adds "مسرعة الجمعيات المتعثرة" as a coming-soon center without services.
-- Skipped when a center with this title already exists, so the record is never duplicated.
INSERT INTO enablement_centers (title, status, price, is_free, short_description, overview, target_audience, methodology, outputs)
SELECT
    'مسرعة الجمعيات المتعثرة',
    'coming_soon',
    0,
    TRUE,
    'مساندة مكثفة للجمعيات المتعثرة، تبدأ بتشخيص تحدياتها وتحديد أولوياتها، ثم إعداد خطة تدخل مخصصة ومتابعة تطبيقها لاستعادة فاعليتها المؤسسية.',
    E'تساند مسرعة الجمعيات المتعثرة الجمعيات التي تواجه تحديات تؤثر في قدرتها على أداء أعمالها وتحقيق رسالتها. وتعمل مع فريق كل جمعية لفهم أسباب التعثر، وتحديد الفجوات ذات الأولوية، وبناء خطة تدخل تتناسب مع واقعها وقدرتها على التطبيق.\n\nتختلف الخدمات وأدوات المساندة من جمعية إلى أخرى بحسب نتائج التشخيص؛ ويُحدّد نطاق التدخل ومخرجاته بالتنسيق مع الجمعية، مع متابعة التنفيذ وتوثيق التحسن والتوصيات اللازمة لاستمرار التطوير.',
    '["الجمعيات الأهلية التي تواجه تعثرًا يؤثر في أدائها المؤسسي، وتحتاج إلى تدخل مخصص، مع استعداد فريقها للمشاركة في التشخيص وتنفيذ إجراءات التحسين."]'::jsonb,
    '[
        {"title": "تشخيص واقع الجمعية", "description": "مراجعة وضع الجمعية ووثائقها ومناقشة فريقها لفهم التحديات وأسباب التعثر."},
        {"title": "تحديد أولويات المعالجة", "description": "تحديد أهم ثلاث فجوات حرجة وترتيبها بحسب تأثيرها في أعمال الجمعية وأولوية معالجتها."},
        {"title": "إعداد خطة تدخل مخصصة", "description": "تحديد الإجراءات والمخرجات والمسؤوليات والجدول الزمني بما يتناسب مع احتياج الجمعية."},
        {"title": "مساندة التنفيذ ومتابعة التطبيق", "description": "تقديم المساندة المتفق عليها، والعمل مع فريق الجمعية على تطبيق الإجراءات ومعالجة عوائق التنفيذ."},
        {"title": "تقييم التحسن والتوصيات", "description": "توثيق ما تحقق وما يحتاج إلى استكمال، وإعداد توصيات تساعد الجمعية على مواصلة التحسين."}
    ]'::jsonb,
    '["تشخيص لحالة الجمعية", "أولويات واضحة للمعالجة", "خطة تدخل مخصصة", "مخرجات تنفيذية تتحدد بحسب الاحتياج", "توثيق لنتائج التدخل والتوصيات النهائية"]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM enablement_centers WHERE title = 'مسرعة الجمعيات المتعثرة');
